The invariant is `0 <= size <= 17`: `head` identifies the next element to pop, and `tail == (head + size) % 17` identifies the next insertion slot. Push rejects a full queue without changing it; pop rejects an empty queue without changing it or the output argument. Advancing indices modulo 17 preserves FIFO order through wraparound.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++size_;
        return true;
    }

    bool pop(int& value) {
        if (size_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

void check(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

int main() {
    BoundedFIFO queue;
    int value = -1;

    check(!queue.pop(value), "Empty pop must fail");
    check(value == -1, "Failed pop changed output");

    // Fill and reject overflow.
    for (int i = 0; i < 17; ++i)
        check(queue.push(i), "Fill failed");
    check(queue.full(), "Queue should be full");
    check(!queue.push(999), "Overflow must be rejected");
    check(queue.size() == 17, "Overflow changed size");

    // Drain, checking that overflow did not alter FIFO contents.
    for (int i = 0; i < 17; ++i) {
        check(queue.pop(value), "Drain failed");
        check(value == i, "Incorrect FIFO order");
    }
    check(queue.empty(), "Queue should be empty");

    // Leave four elements, then insert across the array boundary.
    for (int i = 0; i < 12; ++i)
        check(queue.push(i), "Wrap setup failed");
    for (int i = 0; i < 8; ++i) {
        check(queue.pop(value), "Partial drain failed");
        check(value == i, "Incorrect partial-drain order");
    }
    for (int i = 12; i < 25; ++i)
        check(queue.push(i), "Wrapped push failed");
    check(queue.full(), "Wrapped queue should be full");
    check(!queue.push(999), "Wrapped overflow must fail");

    for (int i = 8; i < 25; ++i) {
        check(queue.pop(value), "Wrapped drain failed");
        check(value == i, "Incorrect wrapped FIFO order");
    }
    check(queue.empty(), "Final queue should be empty");
    value = -1;
    check(!queue.pop(value), "Final empty pop must fail");
    check(value == -1, "Final failed pop changed output");

    std::cout << "All tests passed\n";
}
```

Save as `fifo.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, then run `./fifo`. This implementation is single-threaded; concurrent access requires synchronization.
